#!/usr/bin/env python3
"""Apply script: read Master Client Name / Product Name directly from the
Portfolio Analysis membership export (Column K / Column BD on the real
file), instead of requiring the separate Group->Product and
Subgroup->Master mapping uploads.

Run from the HealthCross repo root: python3 apply_portfolio_inline_master_product.py
"""
import base64, hashlib, os, sys

MARKER = "PORTFOLIO_INLINE_MASTER_PRODUCT_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_portfolio_analysis.py',
        'sha256': 'e3de801d79ac5268d2ce1bf248165da038af4704f0fa0c800aa08dfe42349b2a',
        'size': 19537,
        'b64': '',
    },
    {
        'path': 'app/ingestion/portfolio_members.py',
        'sha256': '5ce432e4edcd4dfb23f2c1a2dd7322939cbc8895aee8b17724371fd650336027',
        'size': 4422,
        'b64': '',
    },
    {
        'path': 'app/models/db_models.py',
        'sha256': '9b00c16f42e7c93cf24ecaa182e41b118d88393c048a42d0846b622022f986d9',
        'size': 28813,
        'b64': '',
    },
    {
        'path': 'app/scoring/rules/portfolio_analysis.py',
        'sha256': 'c0ed4ba751d0cd9a1f90e67ee73b706370f627d35914470329c0396a2ac7960f',
        'size': 20197,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': '694961ca19b2242a4f875319ee40fc65ec81c678ad1815d193bfde792dc4384f',
        'size': 138631,
        'b64': '',
    },
    {
        'path': 'tests/test_ingestion_portfolio_members.py',
        'sha256': '0610dc41d21a07726e03fba2f126921ed87ab5f8adc21303b269fa883c134d55',
        'size': 4794,
        'b64': '',
    },
    {
        'path': 'tests/test_portfolio_analysis.py',
        'sha256': '9b1a897578d6c29063fb84ef1943a7bf391061e7eb56179dc7fecd34971fb6de',
        'size': 28166,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 446 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
        print("Note: your existing underwriting.db will auto-migrate the two new")
        print("columns on the next server start - no manual DB step needed.")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
